import accounts.AccountType;
import accounts.BankUser;
import accounts.CheckingAccount;
import accounts.SavingsAccount;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

/**
 * This class was ai generated by chatGPT. It mirrors the checking account tests and is also verified. Had it re write to onlly include one assertion per test.
 */
public class SavingsAccountTest {
    private CheckingAccount checking;
    private SavingsAccount saving;

    @Before
    public void setUp() {
        BankUser user = new BankUser("test-user", "test-password");
        checking = new CheckingAccount(user, AccountType.CHECKING);
        saving = new SavingsAccount(user, AccountType.SAVINGS);

        user.getAccounts().add(checking);
        user.getAccounts().add(saving);
    }

    @Test
    public void acceptsDepositsAtDailyLimit() {
        saving.deposit(4999);
        saving.deposit(1);

        assertEquals(5000, saving.getBalance());
    }

    @Test
    public void rejectsSingleDepositAboveDailyLimit() {
        assertThrows(IllegalArgumentException.class, () -> saving.deposit(5001));
    }

    @Test
    public void keepsSavingsBalanceAfterSingleOversizedDeposit() {
        attemptRejectedOperation(() -> saving.deposit(5001));

        assertEquals(0, saving.getBalance());
    }

    @Test
    public void rejectsDepositsAboveCumulativeDailyLimit() {
        saving.deposit(1000);

        assertThrows(IllegalArgumentException.class, () -> saving.deposit(4001));
    }

    @Test
    public void keepsSavingsBalanceAfterOversizedCumulativeDeposit() {
        saving.deposit(1000);
        attemptRejectedOperation(() -> saving.deposit(4001));

        assertEquals(1000, saving.getBalance());
    }

    @Test
    public void rejectsZeroDeposit() {
        assertThrows(IllegalArgumentException.class, () -> saving.deposit(0));
    }

    @Test
    public void keepsSavingsBalanceAfterZeroDeposit() {
        attemptRejectedOperation(() -> saving.deposit(0));

        assertEquals(0, saving.getBalance());
    }

    @Test
    public void rejectsNegativeDeposit() {
        assertThrows(IllegalArgumentException.class, () -> saving.deposit(-1));
    }

    @Test
    public void keepsSavingsBalanceAfterNegativeDeposit() {
        attemptRejectedOperation(() -> saving.deposit(-1));

        assertEquals(0, saving.getBalance());
    }

    @Test
    public void debitsSavingsWhenTransferringUpToDailyLimit() {
        transferUpToDailyLimit();

        assertEquals(100, saving.getBalance());
    }

    @Test
    public void creditsCheckingWhenTransferringUpToDailyLimit() {
        transferUpToDailyLimit();

        assertEquals(100, checking.getBalance());
    }

    @Test
    public void rejectsTransferAboveCumulativeDailyLimit() {
        transferUpToDailyLimit();

        assertThrows(IllegalArgumentException.class,
                () -> saving.transfer(1, AccountType.CHECKING));
    }

    @Test
    public void keepsSavingsBalanceAfterTransferAboveDailyLimit() {
        transferUpToDailyLimit();
        attemptRejectedOperation(() -> saving.transfer(1, AccountType.CHECKING));

        assertEquals(100, saving.getBalance());
    }

    @Test
    public void keepsCheckingBalanceAfterTransferAboveDailyLimit() {
        transferUpToDailyLimit();
        attemptRejectedOperation(() -> saving.transfer(1, AccountType.CHECKING));

        assertEquals(100, checking.getBalance());
    }

    @Test
    public void rejectsTransferAboveAvailableBalance() {
        saving.deposit(50);

        assertThrows(IllegalArgumentException.class,
                () -> saving.transfer(51, AccountType.CHECKING));
    }

    @Test
    public void keepsSavingsBalanceAfterTransferAboveBalance() {
        saving.deposit(50);
        attemptRejectedOperation(() -> saving.transfer(51, AccountType.CHECKING));

        assertEquals(50, saving.getBalance());
    }

    @Test
    public void keepsCheckingBalanceAfterTransferAboveBalance() {
        saving.deposit(50);
        attemptRejectedOperation(() -> saving.transfer(51, AccountType.CHECKING));

        assertEquals(0, checking.getBalance());
    }

    private void transferUpToDailyLimit() {
        saving.deposit(200);
        saving.transfer(99, AccountType.CHECKING);
        saving.transfer(1, AccountType.CHECKING);
    }

    private void attemptRejectedOperation(Runnable operation) {
        try {
            operation.run();
        } catch (IllegalArgumentException expected) {
            // Separate tests verify rejection. Here we check the resulting balance.
        }
    }
}
